import React, { useMemo, useState } from "react";
import { Link } from "react-router-dom";
import { useAuth } from "../context/AuthContext";
import "./Dashboard.css";

const STATS_BY_ROLE = {
  USER: [
    { label: "Total bookings made", value: 12 },
    { label: "Active bookings", value: 4, status: "APPROVED" },
    { label: "Pending bookings", value: 2 },
    { label: "Total tickets created", value: 9 },
    { label: "Open tickets", value: 3 }
  ],
  ADMIN: [
    { label: "Total resources", value: 28 },
    { label: "Total bookings", value: 214 },
    { label: "Pending booking approvals", value: 11 },
    { label: "Total tickets", value: 63 },
    { label: "Tickets OPEN / IN_PROGRESS / RESOLVED", value: "18 / 22 / 23" }
  ],
  TECHNICIAN: [
    { label: "Assigned tickets", value: 14 },
    { label: "Tickets in progress", value: 6 },
    { label: "Completed tickets", value: 8 }
  ]
};

const QUICK_ACTIONS_BY_ROLE = {
  USER: ["Create booking", "View my bookings", "Create ticket", "View my tickets"],
  ADMIN: ["Add new resource", "Manage bookings", "Manage tickets"],
  TECHNICIAN: ["View assigned tickets", "Update ticket status"]
};

const NAV_ITEMS = [
  { label: "Dashboard", to: "/" },
  { label: "Resources", to: "/" },
  { label: "Bookings", to: "/" },
  { label: "Tickets", to: "/" },
  { label: "Notifications", to: "/" }
];

const RECENT_BOOKINGS = [
  { id: "BK-1041", item: "Lab Room A", status: "PENDING", at: "2026-04-20 10:30" },
  { id: "BK-1039", item: "Meeting Hall 2", status: "APPROVED", at: "2026-04-19 16:10" },
  { id: "BK-1037", item: "Projector Set", status: "APPROVED", at: "2026-04-19 09:20" },
  { id: "BK-1035", item: "Conference Room", status: "REJECTED", at: "2026-04-18 17:05" },
  { id: "BK-1032", item: "Lab Room C", status: "PENDING", at: "2026-04-18 11:40" }
];

const RECENT_TICKETS = [
  { id: "TK-901", item: "Wi-Fi unstable", status: "OPEN", at: "2026-04-20 11:45" },
  { id: "TK-898", item: "Projector not working", status: "IN_PROGRESS", at: "2026-04-20 09:15" },
  { id: "TK-892", item: "AC leakage", status: "RESOLVED", at: "2026-04-19 14:05" },
  { id: "TK-889", item: "Power outlet issue", status: "OPEN", at: "2026-04-18 15:30" },
  { id: "TK-884", item: "Door lock jam", status: "RESOLVED", at: "2026-04-17 12:00" }
];

const RESOURCE_HIGHLIGHTS = [
  { name: "Lab Room A", type: "Room", capacity: 40, status: "ACTIVE" },
  { name: "Main Hall", type: "Hall", capacity: 120, status: "ACTIVE" },
  { name: "Projector P-12", type: "Equipment", capacity: 1, status: "OUT_OF_SERVICE" },
  { name: "Meeting Room 3", type: "Room", capacity: 15, status: "ACTIVE" },
  { name: "Training Lab", type: "Lab", capacity: 30, status: "ACTIVE" }
];

const NOTIFICATIONS = [
  { id: 1, text: "Booking BK-1041 is awaiting approval.", unread: true, at: "5m ago" },
  { id: 2, text: "Ticket TK-898 moved to IN_PROGRESS.", unread: true, at: "35m ago" },
  { id: 3, text: "Resource Main Hall maintenance completed.", unread: false, at: "2h ago" },
  { id: 4, text: "New booking request submitted by John.", unread: false, at: "4h ago" }
];

const UPCOMING_SCHEDULE = [
  { time: "09:00", title: "Lab Room A - AI Workshop" },
  { time: "11:30", title: "Main Hall - Team Briefing" },
  { time: "14:00", title: "Meeting Room 3 - Client Call" },
  { time: "16:00", title: "Training Lab - Onboarding Session" }
];

function roleFromUser(roles) {
  if ((roles || []).includes("ROLE_ADMIN")) {
    return "ADMIN";
  }

  if ((roles || []).includes("ROLE_TECHNICIAN")) {
    return "TECHNICIAN";
  }

  return "USER";
}

function statusClass(status) {
  return `tag tag-${String(status).toLowerCase().replace(/_/g, "-")}`;
}

function Dashboard() {
  const { user, logout } = useAuth();
  const [query, setQuery] = useState("");
  const [sidebarOpen, setSidebarOpen] = useState(false);

  const currentRole = roleFromUser(user?.roles);
  const stats = STATS_BY_ROLE[currentRole] || STATS_BY_ROLE.USER;
  const quickActions = QUICK_ACTIONS_BY_ROLE[currentRole] || QUICK_ACTIONS_BY_ROLE.USER;
  const unreadCount = NOTIFICATIONS.filter((item) => item.unread).length;

  const searchResults = useMemo(() => {
    const term = query.trim().toLowerCase();
    if (!term) {
      return [];
    }

    const pool = [
      ...RESOURCE_HIGHLIGHTS.map((item) => ({
        type: "Resource",
        title: item.name,
        subtitle: `${item.type} - ${item.status}`
      })),
      ...RECENT_BOOKINGS.map((item) => ({
        type: "Booking",
        title: item.id,
        subtitle: `${item.item} - ${item.status}`
      })),
      ...RECENT_TICKETS.map((item) => ({
        type: "Ticket",
        title: item.id,
        subtitle: `${item.item} - ${item.status}`
      }))
    ];

    return pool.filter((item) => {
      return item.title.toLowerCase().includes(term) || item.subtitle.toLowerCase().includes(term);
    });
  }, [query]);

  return (
    <div className="dashboard-root">
      <header className="dashboard-header">
        <div className="brand-row">
          <button
            type="button"
            className="menu-button"
            onClick={() => setSidebarOpen((value) => !value)}
            aria-label="Toggle navigation"
          >
            {sidebarOpen ? "Close" : "Menu"}
          </button>
          <div>
            <p className="logo-text">PAF PORTAL</p>
            <h1 className="header-title">Home Dashboard</h1>
          </div>
        </div>

        <div className="header-search">
          <input
            type="text"
            placeholder="Search resources, bookings, tickets"
            value={query}
            onChange={(event) => setQuery(event.target.value)}
          />
        </div>

        <div className="profile-row">
          <div className="profile-meta">
            <p className="profile-name">{user?.name || "User"}</p>
            <p className="profile-email">{user?.email || "No email"}</p>
          </div>
          <span className="role-chip">{currentRole}</span>
          <button type="button" className="logout-button" onClick={logout}>
            Logout
          </button>
        </div>
      </header>

      <div className="dashboard-layout">
        <aside className={`sidebar ${sidebarOpen ? "open" : ""}`}>
          <nav>
            <p className="sidebar-title">Navigation</p>
            <ul>
              {NAV_ITEMS.map((item) => (
                <li key={item.label}>
                  <Link to={item.to} onClick={() => setSidebarOpen(false)}>
                    {item.label}
                  </Link>
                </li>
              ))}
            </ul>
          </nav>
        </aside>

        <main className="dashboard-main">
          <section className="panel welcome-panel">
            <h2>Welcome back, {user?.name || "User"}</h2>
            <div className="overview-grid">
              <p><strong>Name:</strong> {user?.name || "-"}</p>
              <p><strong>Email:</strong> {user?.email || "-"}</p>
              <p><strong>Role:</strong> {currentRole}</p>
            </div>
          </section>

          <section className="stats-grid">
            {stats.map((item) => (
              <article key={item.label} className="panel stat-card">
                <p className="stat-label">{item.label}</p>
                <p className="stat-value">{item.value}</p>
                {item.status ? <p className="stat-status">{item.status}</p> : null}
              </article>
            ))}
          </section>

          <section className="double-grid">
            <article className="panel">
              <h3>Recent Activity</h3>
              <p className="section-note">Latest 5 bookings</p>
              <ul className="activity-list">
                {RECENT_BOOKINGS.slice(0, 5).map((item) => (
                  <li key={item.id}>
                    <div>
                      <p className="activity-title">{item.id} - {item.item}</p>
                      <p className="activity-time">{item.at}</p>
                    </div>
                    <span className={statusClass(item.status)}>{item.status}</span>
                  </li>
                ))}
              </ul>

              <p className="section-note">Latest 5 tickets</p>
              <ul className="activity-list">
                {RECENT_TICKETS.slice(0, 5).map((item) => (
                  <li key={item.id}>
                    <div>
                      <p className="activity-title">{item.id} - {item.item}</p>
                      <p className="activity-time">{item.at}</p>
                    </div>
                    <span className={statusClass(item.status)}>{item.status}</span>
                  </li>
                ))}
              </ul>
            </article>

            <article className="panel">
              <h3>Quick Actions</h3>
              <div className="action-grid">
                {quickActions.map((action) => (
                  <button type="button" className="action-button" key={action}>
                    {action}
                  </button>
                ))}
              </div>
            </article>
          </section>

          <section className="double-grid">
            <article className="panel">
              <h3>Resource Highlights</h3>
              <ul className="resource-list">
                {RESOURCE_HIGHLIGHTS.slice(0, 5).map((resource) => (
                  <li key={resource.name}>
                    <div>
                      <p className="resource-name">{resource.name}</p>
                      <p className="resource-meta">{resource.type} - Capacity {resource.capacity}</p>
                    </div>
                    <div className="resource-side">
                      <span className={statusClass(resource.status)}>{resource.status}</span>
                      <Link to="/" className="detail-link">View Details</Link>
                    </div>
                  </li>
                ))}
              </ul>
            </article>

            <article className="panel">
              <h3>Notifications Preview</h3>
              <p className="section-note">Unread: {unreadCount}</p>
              <ul className="notification-list">
                {NOTIFICATIONS.slice(0, 5).map((item) => (
                  <li key={item.id} className={item.unread ? "is-unread" : ""}>
                    <p>{item.text}</p>
                    <span>{item.at}</span>
                  </li>
                ))}
              </ul>
              <Link to="/" className="detail-link">Go to notifications panel</Link>
            </article>
          </section>

          <section className="panel">
            <h3>Calendar / Schedule</h3>
            <p className="section-note">Today and upcoming bookings</p>
            <div className="schedule-grid">
              {UPCOMING_SCHEDULE.map((slot) => (
                <div className="schedule-card" key={slot.time + slot.title}>
                  <p className="schedule-time">{slot.time}</p>
                  <p>{slot.title}</p>
                </div>
              ))}
            </div>
          </section>

          {query.trim() ? (
            <section className="panel">
              <h3>Search Results</h3>
              {searchResults.length ? (
                <ul className="search-results">
                  {searchResults.map((item, index) => (
                    <li key={`${item.type}-${item.title}-${index}`}>
                      <p><strong>{item.type}:</strong> {item.title}</p>
                      <p>{item.subtitle}</p>
                    </li>
                  ))}
                </ul>
              ) : (
                <p>No matches for "{query}".</p>
              )}
            </section>
          ) : null}
        </main>
      </div>
    </div>
  );
}

export default Dashboard;
